  {
    return (
      <div className="App" >
      <h1>
        Learn math with my sidekick!
      </h1>
      <button onClick={()=>{
        setShowShapes(true);
      }}>
        Equations
      </button>
      <button>
        Area, Volume calculations
      </button>
      <canvas id="canvas" width={window.innerWidth} height={window.innerHeight*0.9} class="border border-2"></canvas>
      </div>
